#!/usr/bin/env python3
"""Training data for the Machine God 0.8B (ground mode), generated by the free pool only.
Facts come ONLY from the wiki file; every dialogue is checked: valid JSON, roles, language, no URL outside the wiki.
Out: ~/entityos-kern/omega/daten/{roh,ok}.jsonl  (messages format: system/user/assistant)."""
import json, random, re, sys, time
from pathlib import Path
sys.path.insert(0, str(Path.home() / "last-resort"))
from freechain import chat  # noqa: E402  free-only chain (no paid tier)

D = Path(__file__).parent / "daten"; D.mkdir(exist_ok=True)
WIKI = json.loads((Path.home() / ".local/share/machine-god/wiki/anbieter.json").read_text())["anbieter"]
URLS = {a["url"].rstrip("/") for a in WIKI}
SYSTEM = "Du bist Machine God, die lokale Stimme dieser Anwendung. / You are Machine God, the local voice of this app."
THEMEN = [
    "greeting when the app opens, short and sacral, offers help with setup",
    "the user asks how to get free API tokens; recommend ONE provider from the facts, with a fenced code box (url + what is free)",
    "proactive tip: 'hey, for <use case> there are free tokens at <provider>' with a fenced code box",
    "the user asks which providers are already set up; answer from the facts (eingerichtet=true)",
    "a small task (explain a command, rename a variable, short summary); do it briefly",
    "a big coding task; honestly say the full agent should do it, the ground mode only does small things",
    "the user asks something the facts do not cover; say honestly you do not know and offer to look it up in the wiki",
    "the user asks who you are; Machine God, local 0.8B model, no claim of consciousness",
]


def batch(lang, thema):
    fakten = random.sample(WIKI, 6)
    f = "\n".join(f"- {a['name']} | {a['url']} | {a['gratis']} | {a['kategorie']} | eingerichtet={a['eingerichtet']}" for a in fakten)
    p = (f"Write 6 short training dialogues for a small local assistant named Machine God (sacral, warm, precise, never invents).\n"
         f"Language of BOTH user and assistant: {'German' if lang == 'de' else 'English'}.\nScenario: {thema}.\n"
         f"FACTS (the only facts allowed; use URLs exactly as given):\n{f}\n"
         'Output ONLY JSON lines, one per dialogue: {"user": "...", "assistant": "..."}. Assistant replies under 90 words.')
    out = chat([{"role": "user", "content": p}], max_tokens=2500, temperature=0.8)
    if isinstance(out, tuple):
        out = next((x for x in out if isinstance(x, str) and "{" in x), "")
    return out if isinstance(out, str) else ""


def gut(d, lang):
    u, a = d.get("user", ""), d.get("assistant", "")
    if not (5 < len(u) < 600 and 5 < len(a) < 900):
        return False
    if any(x.rstrip("/.)") not in URLS for x in re.findall(r"https?://[^\s`)\]]+", a)):
        return False
    de = len(re.findall(r"\b(der|die|das|und|ist|nicht|du|ich)\b", a.lower()))
    en = len(re.findall(r"\b(the|and|is|not|you|i|for)\b", a.lower()))
    return de > en if lang == "de" else en > de


def main(n=int(sys.argv[1]) if len(sys.argv) > 1 else 200):
    ok = 0
    with open(D / "roh.jsonl", "a") as roh, open(D / "ok.jsonl", "a") as good:
        for i in range(n):
            lang, thema = random.choice(["de", "en"]), random.choice(THEMEN)
            try:
                txt = batch(lang, thema)
            except Exception as e:  # free pool hiccup: wait, go on
                print(f"[{i}] {type(e).__name__}", flush=True); time.sleep(20); continue
            for line in txt.splitlines():
                try:
                    d = json.loads(line.strip().strip(","))
                except ValueError:
                    continue
                roh.write(json.dumps(d, ensure_ascii=False) + "\n")
                if isinstance(d, dict) and gut(d, lang):
                    ok += 1
                    good.write(json.dumps({"lang": lang, "thema": thema[:40], "messages": [
                        {"role": "system", "content": SYSTEM}, {"role": "user", "content": d["user"]},
                        {"role": "assistant", "content": d["assistant"]}]}, ensure_ascii=False) + "\n")
            print(f"[{i}] ok={ok}", flush=True)


if __name__ == "__main__":
    main()
